from sympy import _new

class CommonMatrix(MatrixExpr):
    """Base class for common matrix operations."""
    def _eval_col_insert(self, pos, other):
        rows = self.rows
        cols = self.cols

        def entry(i, j):
            if j < pos:
                return self[i, j]
            elif j == pos:
                return other[i, 0]
            else:
                return self[i, j - 1]

        return self._new(self.rows, self.cols + other.cols, entry)

    def col_insert(self, pos, other):
        """Inserts column 'other' at position 'pos'."""
        return self._eval_col_insert(pos, other)

    def _eval_col_join(self, other):
        rows = self.rows

        def entry(i, j):
            if i < rows:
                if j < self.cols:
                    return self[i, j]
                else:
                    return other[i - rows, j - self.cols]
            else:
                return other[i - rows, j]

        return self._new(self.rows + other.rows, self.cols, entry)

    def col_join(self, other):
        """Concatenates two matrices along self's last and other's first row."""
        return self._eval_col_join(other)
